input.sparql:
SELECT ?s ?class ?ref ?id WHERE {
  ?s a brick:Building_Electrical_Meter .
  OPTIONAL { ?s ref:hasTimeseriesId ?id }
  OPTIONAL { ?s ref:hasExternalReference ?ref }
}

SELECT ?building ?meter ?id WHERE {
  ?building a brick:Building .
  ?building brick:hasMeter ?meter .
  ?meter a brick:Building_Electrical_Meter .
  OPTIONAL { ?meter ref:hasTimeseriesId ?id }
}
